const menuButton=document.querySelector('.menu-button');const mobileMenu=document.querySelector('.mobile-menu');if(menuButton&&mobileMenu){menuButton.addEventListener('click',()=>{const open=mobileMenu.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(open))});mobileMenu.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{mobileMenu.classList.remove('open');menuButton.setAttribute('aria-expanded','false')}))}
const observer='IntersectionObserver'in window?new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.1}):null;document.querySelectorAll('.reveal').forEach(element=>observer?observer.observe(element):element.classList.add('visible'));document.querySelectorAll('[data-year]').forEach(element=>{element.textContent=new Date().getFullYear()});
const quiz=document.querySelector('[data-pricing-quiz]');if(quiz){const steps=[...quiz.querySelectorAll('.quiz-step')],result=quiz.querySelector('.quiz-result'),progress=quiz.querySelector('.quiz-progress i'),selections={};let current=0;const showStep=index=>{current=index;steps.forEach((step,i)=>{step.hidden=i!==index});result.hidden=true;progress.style.width=`${(index+1)/steps.length*100}%`};steps.forEach((step,index)=>{step.querySelectorAll('.option').forEach(option=>option.addEventListener('click',()=>{step.querySelectorAll('.option').forEach(item=>item.classList.remove('selected'));option.classList.add('selected');selections[step.dataset.question]=Number(option.dataset.score);setTimeout(()=>index<steps.length-1?showStep(index+1):showResult(),160)}));const back=step.querySelector('.quiz-back');if(back)back.addEventListener('click',()=>showStep(Math.max(0,index-1)))});function showResult(){const total=Object.values(selections).reduce((sum,score)=>sum+score,0);const plan=total<=4?{name:'Starter',price:'PKR 150,000',copy:'A focused chatbot for essential questions, branded responses, and a clear customer journey.'}:total<=7?{name:'Growth',price:'PKR 300,000',copy:'A richer lead and support experience with multiple flows, qualification, and business-tool connections.'}:{name:'Custom',price:'PKR 600,000+',copy:'A tailored solution for complex journeys, advanced integrations, multiple audiences, or larger knowledge sets.'};steps.forEach(step=>{step.hidden=true});result.hidden=false;progress.style.width='100%';result.querySelector('[data-result-name]').textContent=`${plan.name} is your best starting point`;result.querySelector('[data-result-price]').textContent=plan.price;result.querySelector('[data-result-copy]').textContent=plan.copy;result.querySelector('[data-result-link]').href=`contact.html?plan=${encodeURIComponent(plan.name)}#inquiry`}quiz.querySelector('[data-restart]').addEventListener('click',()=>{Object.keys(selections).forEach(key=>delete selections[key]);quiz.querySelectorAll('.option').forEach(option=>option.classList.remove('selected'));showStep(0)})}
const contactForm=document.querySelector('[data-contact-form]');if(contactForm){const planSelect=contactForm.querySelector('#plan'),requestedPlan=new URLSearchParams(location.search).get('plan');if(requestedPlan&&[...planSelect.options].some(option=>option.value===requestedPlan))planSelect.value=requestedPlan;contactForm.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(contactForm),subject=encodeURIComponent(`Nexum AI inquiry — ${data.get('plan')||'New project'}`),body=encodeURIComponent(`Name: ${data.get('name')}\nCompany: ${data.get('company')}\nEmail: ${data.get('email')}\nPlan: ${data.get('plan')}\n\nProject details:\n${data.get('message')}`);contactForm.querySelector('.form-status').textContent='Opening your email app with the inquiry details…';location.href=`mailto:info@nexumglobal.solutions?subject=${subject}&body=${body}`})}
